1	package numeric
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync/atomic"
12		"time"
13		"unicode/utf8"
14	)
15	
16	// rawBase64Prefix 标记 _raw 字段中的值是原始字节的 base64 编码。
17	// ':' 不在 base64 字母表内，普通文本（即使本身像 base64，如 "abcd"）
18	// 不会以该前缀开头；而 _raw 字段由本版本写入，旧归档不含此字段，
19	// 因此标记无歧义。
20	const rawBase64Prefix = "base64:"
21	
22	// unmarshalRaw 恢复 rawIdentity 写出的字段；带 base64 前缀的兜底值解码回
23	// 原始字节，普通 JSON 字符串原样返回。
24	func unmarshalRaw(s string) (string, error) {
25		if strings.HasPrefix(s, rawBase64Prefix) {
26			b, err := base64.StdEncoding.DecodeString(s[len(rawBase64Prefix):])
27			if err != nil {
28				return "", fmt.Errorf("numeric: 标识原始字节解码失败: %w", err)
29			}
30			return string(b), nil
31		}
32		return s, nil
33	}
34	
35	// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
36	// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
37	// 保持旧格式归档可直接打开。
38	type identityRaw struct {
39		Submitter string `json:"submitter_raw,omitempty"`
40		RequestID string `json:"request_id_raw,omitempty"`
41	}
42	
43	// rawIdentity 在标识含非法 UTF-8 字节时构造完整字节兜底字段；
44	// 两个标识都是合法 UTF-8 时返回 nil，记录与旧格式完全一致。
45	func rawIdentity(submitter, requestID string) *identityRaw {
46		if utf8.ValidString(submitter) && utf8.ValidString(requestID) {
47			return nil
48		}
49		raw := &identityRaw{}
50		if !utf8.ValidString(submitter) {
51			raw.Submitter = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(submitter))
52		}
53		if !utf8.ValidString(requestID) {
54			raw.RequestID = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(requestID))
55		}
56		return raw
57	}
58	
59	// resolveIdentity 恢复提交人、请求号：_raw 兜底字段存在且非空时以其
60	// 解码出的完整字节为准，否则使用 JSON 字符串字段（旧归档与普通文本）。
61	func resolveIdentity(plainSub, plainReq string, raw *identityRaw) (string, string, error) {
62		var err error
63		sub, req := plainSub, plainReq
64		if raw != nil {
65			if raw.Submitter != "" {
66				if sub, err = unmarshalRaw(raw.Submitter); err != nil {
67					return "", "", err
68				}
69			}
70			if raw.RequestID != "" {
71				if req, err = unmarshalRaw(raw.RequestID); err != nil {
72					return "", "", err
73				}
74			}
75		}
76		return sub, req, nil
77	}
78	
79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		r := jobRecord{
149			Version: recordVersion,
150	
151			ID:            j.id,
152			Submitter:     j.submitter,
153			RequestID:     j.requestID,
154			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
155			Seed:          j.seed,
156			Values:        append([]int64(nil), j.values...),
157			HasDependency: len(j.dependencies) > 0,
158			DependencyID:  depID(j),
159			Dependencies:  append([]uint64(nil), j.dependencies...),
160	
161			QueuedAt:      j.queuedAt,
162			StartedAt:     j.startedAt,
163			FinishedAt:    j.finishedAt,
164			Status:        j.status,
165			FailureReason: j.failureReason,
166			BlockerID:     j.blockerID,
167	
168			EffectiveValues: append([]int64(nil), j.effectiveValues...),
169			Archive:         j.archive,
170		}
171		return json.MarshalIndent(&r, "", "  ")
172	}
173	
174	// depID 返回首个直接上游作业号（无依赖时为 0）。
175	func depID(j *storedJob) uint64 {
176		if len(j.dependencies) == 0 {
177			return 0
178		}
179		return j.dependencies[0]
180	}
181	
182	// persist 在已持锁的情况下原子写一条作业记录。
183	func (s *Store) persist(j *storedJob) error {
184		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
185		if s.persistFault != nil {
186			if err := s.persistFault(j); err != nil {
187				return err
188			}
189		}
190		data, err := encodeRecord(j)
191		if err != nil {
192			return err
193		}
194		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
195	}
196	
197	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
198	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
199	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
200		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
201		if err != nil {
202			return err
203		}
204		tmpName := tmp.Name()
205		cleanup := true
206		defer func() {
207			if cleanup {
208				_ = os.Remove(tmpName)
209			}
210		}()
211	
212		if _, err := tmp.Write(data); err != nil {
213			_ = tmp.Close()
214			return err
215		}
216		if err := tmp.Sync(); err != nil {
217			_ = tmp.Close()
218			return err
219		}
220		if err := tmp.Close(); err != nil {
221			return err
222		}
223		if err := os.Chmod(tmpName, perm); err != nil {
224			return err
225		}
226		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
227			return err
228		}
229		cleanup = false
230		syncDir(dir)
231		return nil
232	}
233	
234	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
235	func syncDir(dir string) {
236		if d, err := os.Open(dir); err == nil {
237			_ = d.Sync()
238			_ = d.Close()
239		}
240	}
241	
242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，实际输入与原始参数或直接依赖数量
247	//     不对应，或归档数值结果与有效输入按计算规则应得的结果不符时，
248	//     fail-closed 地标记为失败，维持“成功必有完整归档”的不变量；
249	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
250	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
251	//     排列的总和；对不上或上游不可用的同样改判为失败。
252	func loadDir(dir string) ([]*storedJob, uint64, error) {
253		entries, err := os.ReadDir(dir)
254		if err != nil {
255			return nil, 0, err
256		}
257		var jobs []*storedJob
258		var maxID uint64
259		for _, e := range entries {
260			name := e.Name()
261			if e.IsDir() {
262				continue
263			}
264			// 清理上一进程崩溃时可能残留的原子写临时文件。
265			if strings.HasPrefix(name, ".tmp-") {
266				_ = os.Remove(filepath.Join(dir, name))
267				continue
268			}
269			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
270				continue
271			}
272			path := filepath.Join(dir, name)
273			data, err := os.ReadFile(path)
274			if err != nil {
275				return nil, 0, err
276			}
277			var r jobRecord
278			if err := json.Unmarshal(data, &r); err != nil {
279				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
280			}
281			if r.Version != recordVersion {
282				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
283			}
284			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
285			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
286			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
287			if err != nil {
288				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
289			}
290			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
291			// 与归档中的参数逐字节一致。
292			if r.Archive != nil {
293				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
294				if aErr != nil {
295					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
296				}
297				r.Archive.Submitter = aSub
298				r.Archive.RequestID = aReq
299			}
300			switch r.Status {
301			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
302			default:
303				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
304			}
305			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
306			// 恢复为只含一个作业号的列表（语义与提交时一致）。
307			deps := append([]uint64(nil), r.Dependencies...)
308			if len(deps) == 0 && r.HasDependency {
309				deps = []uint64{r.DependencyID}
310			}
311			j := &storedJob{
312				id:           r.ID,
313				submitter:    submitter,
314				requestID:    requestID,
315				seed:         r.Seed,
316				values:       append([]int64(nil), r.Values...),
317				dependencies: deps,
318	
319				queuedAt:   r.QueuedAt,
320				startedAt:  r.StartedAt,
321				finishedAt: r.FinishedAt,
322	
323				status:        r.Status,
324				failureReason: r.FailureReason,
325				blockerID:     r.BlockerID,
326	
327				effectiveValues: append([]int64(nil), r.EffectiveValues...),
328				archive:         r.Archive,
329			}
330			if j.status == StatusRunning {
331				j.status = StatusFailed
332				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
333				j.blockerID = 0
334				if j.finishedAt.IsZero() {
335					j.finishedAt = time.Now().UTC()
336				}
337				j.effectiveValues = nil
338				j.archive = nil
339				// 就地重写恢复后的终态。
340				if data, err := encodeRecord(j); err == nil {
341					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
342				}
343			}
344			if j.status == StatusSucceeded {
345				// 除完整性外，还必须满足两条独立的对应/复算规则：
346				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
347				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
348				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
349				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
350				//     原始参数与依赖数量才能识别。
351				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
352				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
353				//     输入复算才能识别。
354				// 任一不符合都按损坏归档处理。第三条规则——追加部分逐项等于各
355				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
356				// 在排序后的第二趟扫描中执行。
357				var invalidReason string
358				switch {
359				case !archiveIntact(j):
360					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
361				case !effectiveInputsCorrespond(j):
362					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
363				case !archiveResultsValid(j):
364					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
365				}
366				if invalidReason != "" {
367					j.status = StatusFailed
368					j.failureReason = invalidReason
369					if j.finishedAt.IsZero() {
370						j.finishedAt = time.Now().UTC()
371					}
372					j.effectiveValues = nil
373					j.archive = nil
374					if data, err := encodeRecord(j); err == nil {
375						_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
376					}
377				}
378			}
379			jobs = append(jobs, j)
380			if j.id > maxID {
381				maxID = j.id
382			}
383		}
384		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
385		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
386		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
387		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
388		// 依赖链在单趟级联扫描中漏掉失败传播）。
389		sort.Slice(jobs, func(a, b int) bool {
390			return jobs[a].id < jobs[b].id
391		})
392		// 第二趟校验：有依赖的成功记录，其实际输入的追加部分必须与直接上游
393		// 恢复后的结果逐项对应。上游作业号必然更小，按升序单趟扫描即可让
394		// “上游本次被改判失败”沿成功链条传播到更下游——下游看到的一定是
395		// 上游已经确定的最终状态。
396		byID := make(map[uint64]*storedJob, len(jobs))
397		for _, j := range jobs {
398			byID[j.id] = j
399		}
400		for _, j := range jobs {
401			if j.status != StatusSucceeded || len(j.dependencies) == 0 {
402				continue
403			}
404			reason := dependencyInputsFailure(j, byID)
405			if reason == "" {
406				continue
407			}
408			j.status = StatusFailed
409			j.failureReason = reason
410			if j.finishedAt.IsZero() {
411				j.finishedAt = time.Now().UTC()
412			}
413			j.effectiveValues = nil
414			j.archive = nil
415			// 可正常写入时，保存的记录同样改写为失败。
416			if data, err := encodeRecord(j); err == nil {
417				_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
418			}
419		}
420		return jobs, maxID, nil
421	}
422	
423	// dependencyInputsFailure 核对有依赖的成功记录：实际输入的追加部分（原始
424	// 序列之后的 len(dependencies) 个位置）必须与直接上游恢复后的结果对应——
425	//   - 每个直接上游都必须存在、恢复后仍是成功状态且带有通过全部校验的完整
426	//     归档；上游在本次打开中被其他校验改判失败的，本作业也不能继续使用它；
427	//   - 追加部分逐项等于这些上游按保存的依赖顺序排列的总和。负数、零以及
428	//     不同上游恰好同和都按位置判断，不要求上游总和互不相同。
429	//
430	// 返回空串表示对应关系成立；否则返回指出具体直接上游作业号、并说明成功
431	// 结果不可用的失败原因。只读上游状态，绝不因下游追加值错误改动上游。
432	//
433	// 调用前须已通过 effectiveInputsCorrespond（保证追加部分长度恰为依赖数量）。
434	func dependencyInputsFailure(j *storedJob, byID map[uint64]*storedJob) string {
435		n := len(j.values)
436		for i, id := range j.dependencies {
437			dep := byID[id]
438			if dep == nil || dep.status != StatusSucceeded || dep.archive == nil {
439				return fmt.Sprintf("直接上游作业 %d 无法使用：不存在或恢复后未保持带完整归档的成功状态，成功结果不可用", id)
440			}
441			if j.effectiveValues[n+i] != dep.archive.Sum {
442				return fmt.Sprintf("实际输入的追加部分与直接上游作业 %d 的总和无法对应（追加值须按保存的依赖顺序逐项等于各上游总和），成功结果不可用", id)
443			}
444		}
445		return ""
446	}
447	
448	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
449	func archiveIntact(j *storedJob) bool {
450		a := j.archive
451		if a == nil {
452			return false
453		}
454		// 归档中的原始参数必须与记录顶层字段一致。
455		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
456			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
457			return false
458		}
459		if a.HasDependency && a.DependencyID != depID(j) {
460			return false
461		}
462		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
463		// 由单依赖字段推导后再比较。
464		aDeps := append([]uint64(nil), a.Dependencies...)
465		if len(aDeps) == 0 && a.HasDependency {
466			aDeps = []uint64{a.DependencyID}
467		}
468		if len(aDeps) != len(j.dependencies) {
469			return false
470		}
471		for i := range j.dependencies {
472			if aDeps[i] != j.dependencies[i] {
473				return false
474			}
475		}
476		if len(a.Values) != len(j.values) {
477			return false
478		}
479		for i := range j.values {
480			if a.Values[i] != j.values[i] {
481				return false
482			}
483		}
484		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
485			return false
486		}
487		for i := range j.effectiveValues {
488			if j.effectiveValues[i] != a.EffectiveValues[i] {
489				return false
490			}
491		}
492		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
493			return false
494		}
495		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
496			return false
497		}
498		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
499			return false
500		}
501		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
502			return false
503		}
504		return true
505	}
506	
507	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
508	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
509	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
510	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
511	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
512	// （包括回绕后的值）都不能作为有效成功结果保留。
513	//
514	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
515	func archiveResultsValid(j *storedJob) bool {
516		a := j.archive
517		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
518		if !ok {
519			return false
520		}
521		return a.Sum == sum && a.SumOfSquares == sumSquares
522	}
523	
524	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
525	// 参数、直接依赖数量之间的对应关系：
526	//   - 原始序列必须非空；
527	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
528	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
529	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
530	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
531	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
532	//     能多出未记录的输入。
533	//
534	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
535	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
536	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
537	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
538	//
539	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
540	// 副本与顶层一致）。
541	func effectiveInputsCorrespond(j *storedJob) bool {
542		n := len(j.values)
543		if n == 0 {
544			return false
545		}
546		if len(j.effectiveValues) != n+len(j.dependencies) {
547			return false
548		}
549		for i := 0; i < n; i++ {
550			if j.effectiveValues[i] != j.values[i] {
551				return false
552			}
553		}
554		return true
555	}
556

