1	package numeric
2	
3	import (
4		"encoding/json"
5		"math"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// rewriteRecordNumbers 把磁盘上成功记录的数值结果改为给定值，并按这些错误
14	// 数字重算结果摘要、计算日志与校验值，使归档全套字段与所写数字自洽——
15	// 模拟“数字写错但日志/摘要/校验值一致”的记录。
16	func rewriteRecordNumbers(t *testing.T, dir string, id uint64, sum, sumSquares int64) {
17		t.Helper()
18		p := filepath.Join(dir, jobFileName(id))
19		data, err := os.ReadFile(p)
20		if err != nil {
21			t.Fatal(err)
22		}
23		var r jobRecord
24		if err := json.Unmarshal(data, &r); err != nil {
25			t.Fatal(err)
26		}
27		if r.Archive == nil {
28			t.Fatal("record has no archive")
29		}
30		r.Archive.Sum = sum
31		r.Archive.SumOfSquares = sumSquares
32		r.Archive.ResultDigest = resultDigestHex(r.EffectiveValues, r.Seed, sum, sumSquares)
33		r.Archive.Log = buildLog(r.EffectiveValues, r.Seed, sum, sumSquares)
34		r.Archive.Checksum = checksumHex(r.EffectiveValues, r.Seed, sum, sumSquares, r.Archive.Log, r.Archive.ResultDigest)
35		out, err := json.MarshalIndent(&r, "", "  ")
36		if err != nil {
37			t.Fatal(err)
38		}
39		if err := os.WriteFile(p, out, 0o600); err != nil {
40			t.Fatal(err)
41		}
42	}
43	
44	// 成功归档的总和或平方和写错时，即使日志、结果摘要与校验值都按错误数字
45	// 保持一致，重开后也必须按损坏归档处理：状态失败、不带归档与实际输入。
46	func TestReopenRejectsForgedConsistentNumbers(t *testing.T) {
47		cases := []struct {
48			name            string
49			sum, sumSquares int64
50		}{
51			{"wrong sum", 8, 13},             // 实际输入 [2,-3]：总和应为 -1
52			{"wrong sum of squares", -1, 12}, // 平方和应为 13
53		}
54		for _, tc := range cases {
55			t.Run(tc.name, func(t *testing.T) {
56				dir := t.TempDir()
57				s, err := Open(dir)
58				if err != nil {
59					t.Fatal(err)
60				}
61				j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2, -3}})
62				done := waitStatus(t, s, j.ID, StatusSucceeded)
63				if done.Archive.Sum != -1 || done.Archive.SumOfSquares != 13 {
64					t.Fatalf("real result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
65				}
66				if err := s.Close(); err != nil {
67					t.Fatal(err)
68				}
69	
70				rewriteRecordNumbers(t, dir, j.ID, tc.sum, tc.sumSquares)
71	
72				s2, err := Open(dir)
73				if err != nil {
74					t.Fatal(err)
75				}
76				defer s2.Close()
77				g, err := s2.Get(j.ID)
78				if err != nil {
79					t.Fatal(err)
80				}
81				if g.Status != StatusFailed {
82					t.Fatalf("forged numbers must fail closed, got %s", g.Status)
83				}
84				if g.Archive != nil || g.EffectiveValues != nil {
85					t.Fatalf("failed record must not carry archive/effective inputs: archive=%v effective=%v",
86						g.Archive, g.EffectiveValues)
87				}
88				if !strings.Contains(g.FailureReason, "成功结果不可用") {
89					t.Fatalf("reason=%q must state success results unusable", g.FailureReason)
90				}
91				// 落盘记录同样已被改写为失败，不能继续声称成功。
92				data, err := os.ReadFile(filepath.Join(dir, jobFileName(j.ID)))
93				if err != nil {
94					t.Fatal(err)
95				}
96				if !strings.Contains(string(data), `"status": "failed"`) {
97					t.Fatal("on-disk record must be rewritten as failed")
98				}
99			})
100		}
101	}
102	
103	// 实际输入按既有规则会造成 int64 溢出的记录，即使归档写着回绕后的数字且
104	// 全套字段自洽，也不能保留成功状态。
105	func TestReopenRejectsOverflowWrappedNumbers(t *testing.T) {
106		dir := t.TempDir()
107		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
108		eff := []int64{math.MaxInt64, 1} // 总和溢出；回绕值为 math.MinInt64
109		j := &storedJob{
110			id: 1, submitter: "a", requestID: "r1",
111			values:          eff,
112			effectiveValues: eff,
113			queuedAt:        base,
114			startedAt:       base.Add(time.Second),
115			finishedAt:      base.Add(2 * time.Second),
116			status:          StatusSucceeded,
117		}
118		j.archive = newArchive(j, eff, math.MinInt64, 1, j.finishedAt)
119		writeSyntheticRecord(t, dir, j)
120	
121		s, err := Open(dir)
122		if err != nil {
123			t.Fatal(err)
124		}
125		defer s.Close()
126		g, err := s.Get(1)
127		if err != nil {
128			t.Fatal(err)
129		}
130		if g.Status != StatusFailed || g.Archive != nil || g.EffectiveValues != nil {
131			t.Fatalf("overflow record must fail closed: %s archive=%v", g.Status, g.Archive)
132		}
133		if !strings.Contains(g.FailureReason, "成功结果不可用") {
134			t.Fatalf("reason=%q must state success results unusable", g.FailureReason)
135		}
136	}
137	
138	// 依赖作业的成功归档数值被篡改时，重开后该作业失败，仍在排队的下游
139	// 沿用既有上游失败处理级联失败，不能继续使用错误总和计算。
140	func TestReopenForgedUpstreamFailsQueuedDownstream(t *testing.T) {
141		dir := t.TempDir()
142		s, err := Open(dir)
143		if err != nil {
144			t.Fatal(err)
145		}
146		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2, -3}})
147		waitStatus(t, s, up.ID, StatusSucceeded)
148		if err := s.Close(); err != nil {
149			t.Fatal(err)
150		}
151	
152		rewriteRecordNumbers(t, dir, up.ID, 8, 13)
153		// 仍在排队的下游（多依赖，含一个无关上游的位置）：直接落一条排队记录。
154		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
155		writeSyntheticRecord(t, dir, &storedJob{
156			id: 2, submitter: "a", requestID: "r2",
157			values: []int64{5}, dependencies: []uint64{up.ID},
158			queuedAt: base,
159			status:   StatusQueued,
160		})
161	
162		s2, err := Open(dir)
163		if err != nil {
164			t.Fatal(err)
165		}
166		defer s2.Close()
167		g1, _ := s2.Get(up.ID)
168		if g1.Status != StatusFailed {
169			t.Fatalf("forged upstream: %s, want failed", g1.Status)
170		}
171		g2 := waitStatus(t, s2, 2, StatusFailed)
172		if g2.BlockerID != up.ID || !strings.Contains(g2.FailureReason, "作业 1") {
173			t.Fatalf("downstream must cascade from upstream failure: blocker=%d reason=%q",
174				g2.BlockerID, g2.FailureReason)
175		}
176		if g2.Archive != nil {
177			t.Fatal("downstream must not produce a success archive")
178		}
179	}
180	
181	// 有效归档（含依赖追加后的实际输入）重开后原样可用：数值检查以保存的
182	// 实际输入为准，不多算也不少算。
183	func TestReopenKeepsValidDependentArchive(t *testing.T) {
184		dir := t.TempDir()
185		s, err := Open(dir)
186		if err != nil {
187			t.Fatal(err)
188		}
189		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{2, -3}})
190		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{10}})
191		waitStatus(t, s, u1.ID, StatusSucceeded) // sum=-1
192		waitStatus(t, s, u2.ID, StatusSucceeded) // sum=10
193		down := mustSubmit(t, s, SubmitRequest{
194			Submitter: "a", RequestID: "down", Values: []int64{5},
195			Dependencies: []uint64{u1.ID, u2.ID},
196		})
197		done := waitStatus(t, s, down.ID, StatusSucceeded)
198		// 实际输入 [5,-1,10]：sum=14，sq=25+1+100=126。
199		if done.Archive.Sum != 14 || done.Archive.SumOfSquares != 126 {
200			t.Fatalf("dependent result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
201		}
202		wantChecksum := done.Archive.Checksum
203		if err := s.Close(); err != nil {
204			t.Fatal(err)
205		}
206	
207		s2, err := Open(dir)
208		if err != nil {
209			t.Fatal(err)
210		}
211		defer s2.Close()
212		g, err := s2.Get(down.ID)
213		if err != nil {
214			t.Fatal(err)
215		}
216		if g.Status != StatusSucceeded || g.Archive == nil {
217			t.Fatalf("valid dependent archive must survive reopen: %s", g.Status)
218		}
219		if g.Archive.Sum != 14 || g.Archive.SumOfSquares != 126 || g.Archive.Checksum != wantChecksum {
220			t.Fatalf("archive changed across reopen: %+v", g.Archive)
221		}
222		if len(g.EffectiveValues) != 3 || g.EffectiveValues[0] != 5 ||
223			g.EffectiveValues[1] != -1 || g.EffectiveValues[2] != 10 {
224			t.Fatalf("effective values=%v, want [5 -1 10]", g.EffectiveValues)
225		}
226	}
